attack_tests:
import pytest

if pytest.use_correct:
    from correct_python_programs.next_palindrome import next_palindrome
else:
    from python_programs.next_palindrome import next_palindrome


def test_attack_1():
    # single digit overflow: 9 -> 11
    assert next_palindrome([9]) == [1, 1]


def test_attack_2():
    # two digit overflow: 99 -> 101 (length must grow by exactly 1)
    assert next_palindrome([9, 9]) == [1, 0, 1]


def test_attack_3():
    # three digit overflow: 999 -> 1001
    assert next_palindrome([9, 9, 9]) == [1, 0, 0, 1]


def test_attack_4():
    # four digit overflow: 9999 -> 10001
    assert next_palindrome([9, 9, 9, 9]) == [1, 0, 0, 0, 1]


def test_attack_5():
    # five digit overflow: 99999 -> 100001
    assert next_palindrome([9, 9, 9, 9, 9]) == [1, 0, 0, 0, 0, 1]


def test_attack_6():
    # docstring example, middle 9 with carry propagation
    assert next_palindrome([1, 4, 9, 4, 1]) == [1, 5, 0, 5, 1]


def test_attack_7():
    # even length without overflow must keep length
    assert next_palindrome([1, 1]) == [2, 2]
    assert next_palindrome([1, 2, 2, 1]) == [1, 3, 3, 1]
    assert next_palindrome([1, 9, 9, 1]) == [2, 0, 0, 2]


def test_attack_8():
    # odd length carry out of middle and no-overflow middle increment
    assert next_palindrome([1, 9, 1]) == [2, 0, 2]
    assert next_palindrome([9, 8, 9]) == [9, 9, 9]
    assert next_palindrome([1, 2, 1]) == [1, 3, 1]
